const input = $json;

if (!input.analysis_run_id) {
  throw new Error(
    '[Проверить результат финализации] Нет analysis_run_id'
  );
}

if (typeof input.finalization_state !== 'string') {
  throw new Error(
    '[Проверить результат финализации] Нет finalization_state'
  );
}

// ------------------------------------------------------------
// Ошибочные состояния.
// Их нельзя молча трактовать как "ещё не готово".
// ------------------------------------------------------------

const hardErrors = new Set([
  'run_not_found',
  'invalid_lifecycle_ready_for_aggregation',
  'invalid_lifecycle_status',
  'completion_not_claimed',
]);

if (hardErrors.has(input.finalization_state)) {
  throw new Error(
    `[Проверить результат финализации] Ошибка финализации run ${input.analysis_run_id}: ` +
    `${input.finalization_state}; ` +
    `run_status_before=${input.run_status_before ?? 'null'}; ` +
    `final_count=${input.final_count ?? 'null'}; ` +
    `missing_keys=${JSON.stringify(input.missing_keys ?? [])}; ` +
    `unexpected_keys=${JSON.stringify(input.unexpected_keys ?? [])}; ` +
    `invalid_status_keys=${JSON.stringify(input.invalid_status_keys ?? [])}; ` +
    `invalid_catalog_keys=${JSON.stringify(input.invalid_catalog_keys ?? [])}; ` +
    `invalid_contract_keys=${JSON.stringify(input.invalid_contract_keys ?? [])}`
  );
}

// ------------------------------------------------------------
// Допустимые состояния.
//
// waiting_for_final_fields:
//   пока не все 27 FINAL готовы.
//
// completed_now:
//   именно этот execution атомарно завершил run.
//
// already_completed:
//   повторный безопасный вызов Finalizer.
// ------------------------------------------------------------

const allowedStates = new Set([
  'waiting_for_final_fields',
  'completed_now',
  'already_completed',
]);

if (!allowedStates.has(input.finalization_state)) {
  throw new Error(
    `[Проверить результат финализации] Неизвестное состояние: ${input.finalization_state}`
  );
}

return [
  {
    json: input,
  },
];
